(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.035+t*0.5+1.2)*8 + Math.cos(y*0.028-t*0.4)*6;
  const w2y = Math.cos(y*0.032-t*0.45+0.8)*8 + Math.sin(x*0.025+t*0.55)*6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65)*90, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*70, 200+Math.sin(t*0.75+1)*80, 0.065, 2.4, 1.05],
    [200+Math.sin(t*0.38+4.5)*130, 10+Math.cos(t*0.58+3)*60, 0.095, 1.8, 0.95],
    [300+Math.cos(t*0.42+1.5)*100, 230+Math.sin(t*0.52+2.5)*40, 0.075, 2.2, 1.15]
  ];
  let aS = 0, iS = 0, cS = 0;
  for (const [sX, sY, f, sp, am] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * am;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * am;
    cS += Math.sin(d*f*1.3 - t*sp*0.4 + 3.0) * am * 0.5;
  }
  const n = 10;
  const act = aS/n, inh = iS/n, cou = cS/n;
  const fb1 = Math.sin(act*2.5 - inh*1.8 + t*0.3)*0.15;
  const fb2 = Math.cos(cou*2.0 + act*1.5 - t*0.4)*0.1;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07+sy*0.05+t*1.8)*0.15 + Math.sin(sx*0.02-sy*0.06+t*0.7)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
