    + Math.sin(dist*0.07-ang*5+t*0.9)*0.5 + Math.cos(dist*0.03+ang*2-t*2.0)*0.4)*0.3;
  const radial = Math.sin(dist*0.08 - t*1.3)*Math.cos(ang*2 + t*0.5)*0.2;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+t*2.2)*Math.sin(sy*0.25-t*1.8)*0.08;
  const combined = act - inh*0.7 + bg*0.3 + spiral + radial + fb1 + fb2 + cou*0.4;
  const reaction = Math.tanh(combined*2.0);
  const breath = 0.92 + Math.sin(t*0.25)*0.08;
  const blend = reaction*0.6 + cell*0.2 + micro*0.1 + fb2*0.1;
  const v = Math.tanh(blend*1.8*breath)*0.5+0.5;
  const pal = [
    [5,12,55],[12,35,88],[8,65,105],[15,110,115],
    [45,160,140],[130,195,150],[210,210,120],
    [240,175,80],[230,120,65],[190,60,75],
    [120,30,85],[60,15,65],[5,12,55]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85 + Math.sin(reaction*Math.PI)*0.15;
  const edge = Math.abs(reaction)>0.65 ? 1.0 + (Math.abs(reaction)-0.65)*0.6 : 1.0;
  const glow = Math.max(0, reaction)*0.12;
  const vig = 1.0 - Math.pow(dist/320, 2.5)*0.3;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*80)*vig)|0,
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*60)*vig)|0,
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*120)*vig)|0
  ];
}
